      "number": 20,
      "arFull": "اِنَّهُمْ اِنْ یَّظْهَرُوْا عَلَیْكُمْ یَرْجُمُوْكُمْ اَوْ یُعِیْدُوْكُمْ فِیْ مِلَّتِهِمْ وَلَنْ تُفْلِحُوْۤا اِذًا اَبَدًا ۟",
      "ur": "اگر یہ کافر تم پر غلبہ پالیں تو تمہیں سنگسار کر دیں گے یا تمہیں پھر اپنے دین میں لوٹا لیں گے اور پھر تم کبھی بھی کامیاب نہ ہو سکو گے.[1]",
      "en": "Indeed, if they come to know of you, they will stone you or return you to their religion. And never would you succeed, then - ever.\"",
      "footnotesUr": "[1] یعنی آخرت کی جس کامیابی کے لئے ہم نے صعوبت، مشقت برداشت کی، ظاہر بات ہے کہ اگر اہل شہر نے ہمیں مجبور کرکے پھر آبائی دین کی طرف لوٹا دیا، تو ہمارا اصل مقصد ہی فوت ہو جائے گا، ہماری محنت بھی برباد جائے گی اور ہم نہ دین کے رہیں گے نہ دنیا کے۔",
