      "arFull": "قُلِ اللّٰهُ اَعْلَمُ بِمَا لَبِثُوْا ۚ لَهٗ غَیْبُ السَّمٰوٰتِ وَالْاَرْضِ ؕ اَبْصِرْ بِهٖ وَاَسْمِعْ ؕ مَا لَهُمْ مِّنْ دُوْنِهٖ مِنْ وَّلِیٍّ ؗ وَّلَا یُشْرِكُ فِیْ حُكْمِهٖۤ اَحَدًا ۟",
