      "ur": "اور نہ میں قیامت کو قائم ہونے والی خیال کرتا ہوں اور اگر (بالفرض) میں اپنے رب کی طرف لوٹایا بھی گیا تو یقیناً میں (اس لوٹنے کی جگہ) اس سے بھی زیاده[1] بہتر پاؤں گا.",
      "en": "And I do not think the Hour will occur. And even if I should be brought back to my Lord, I will surely find better than this as a return.\"",
      "footnotesUr": "[1] یعنی وہ کافر عجب اور غرور میں ہی مبتلا نہیں ہوا بلکہ اس کی مد ہوشی اور مستقبل کی حسین اور لمبی امیدوں نے اسے اللہ کی گرفت اور سزا کے عمل سے بالکل غافل کر دیا۔ علاوہ ازیں اس نے قیامت کا ہی انکار کر دیا، پھر مذاق کا مظاہرہ کرتے ہوئے کہا کہ اگر قیامت برپا ہوئی بھی تو وہاں بھی حسن انجام میرا مقدر ہوگا۔ جن کا کفر طغیان حد سے تجاوز کر جاتا ہے، وہ مست مئے پندار ہو کر ایسے ہی متکبرانہ دعوے کرتے ہیں۔ جیسے دوسرے مقام پر اللہ تعالٰی نے فرمایا: «وَلَئِنْ رُجِعْتُ إِلَى رَبِّي إِنَّ لِي عِنْدَهُ لَلْحُسْنَى» (حم السجدة: 50)۔ اگر مجھے رب کی طرف لوٹایا گیا تو وہاں بھی میرے لیے اچھائیاں ہی ہیں۔ «أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا وَقَالَ لأُوتَيَنَّ مَالا وَوَلَدًا» (مريم:77)۔ کیا آپ نے اس شخص کو دیکھا جس نے ہماری آیتوں کے ساتھ کفر کیا اور دعوی کیا کہ آخرت میں بھی مجھے مال و اولاد سے نوازا جائے گا۔",
      "footnotesEn": null,
