      "en": "So they set out, until when they had embarked on the ship, he [i.e., al-Khiḍr] tore it open. [Moses] said, \"Have you torn it open to drown its people? You have certainly done a grave thing.\"",
      "footnotesUr": "[1] حضرت موسیٰ (عليه السلام) کو چونکہ اس علم خاص کی خبر نہیں تھی جس کی بنا پر خضر نے کشتی کے تختے توڑ دیئے تھے، اس لئے صبر نہ کر سکے اور اپنے علم و فہم کے مطابق اسے نہایت ہولناک کام قرارا دیا۔ إِمْرًا کے معنی ہیں الدَّاهِيَةُ الْعَظِيمَةُ، ”بڑا ہیبت ناک کام“۔",
