      "arFull": "اَمَّا السَّفِیْنَةُ فَكَانَتْ لِمَسٰكِیْنَ یَعْمَلُوْنَ فِی الْبَحْرِ فَاَرَدْتُّ اَنْ اَعِیْبَهَا وَكَانَ وَرَآءَهُمْ مَّلِكٌ یَّاْخُذُ كُلَّ سَفِیْنَةٍ غَصْبًا ۟",
