      "arFull": "حَتّٰۤی اِذَا بَلَغَ بَیْنَ السَّدَّیْنِ وَجَدَ مِنْ دُوْنِهِمَا قَوْمًا ۙ لَّا یَكَادُوْنَ یَفْقَهُوْنَ قَوْلًا ۟",
      "ur": "یہاں تک کہ جب دو دیواروں[1] کے درمیان پہنچا ان دونوں کے پرے اس نے ایک ایسی قوم پائی جو بات سمجھنے کے قریب بھی نہ تھی.[2]",
      "en": "Until, when he reached [a pass] between two mountains, he found beside them a people who could hardly understand [his] speech.",
      "footnotesUr": "[1] اس سے مراد دو پہاڑ ہیں جو ایک دوسرے کے مقابل تھے، ان کے درمیان کھائی تھی، جس سے یاجوج و ماجوج ادھر آبادی میں آ جاتے اور اودھم مچاتے اور قتل وغارت گری کا بازار گرم کرتے۔\n[2] یعنی اپنی زبان کے سوا کسی اور کی زبان نہیں سمجھتے تھے۔",
