      "arFull": "ذٰلِكَ جَزَآؤُهُمْ جَهَنَّمُ بِمَا كَفَرُوْا وَاتَّخَذُوْۤا اٰیٰتِیْ وَرُسُلِیْ هُزُوًا ۟",
