      "number": 110,
      "arFull": "قُلْ اِنَّمَاۤ اَنَا بَشَرٌ مِّثْلُكُمْ یُوْحٰۤی اِلَیَّ اَنَّمَاۤ اِلٰهُكُمْ اِلٰهٌ وَّاحِدٌ ۚ فَمَنْ كَانَ یَرْجُوْا لِقَآءَ رَبِّهٖ فَلْیَعْمَلْ عَمَلًا صَالِحًا وَّلَا یُشْرِكْ بِعِبَادَةِ رَبِّهٖۤ اَحَدًا ۟۠",
      "ur": "آپ کہہ دیجئے کہ میں تو تم جیسا ہی ایک انسان ہوں[1] - (ہاں) میری جانب وحی کی جاتی ہے کہ سب کا معبود صرف ایک ہی معبود ہے[2]، تو جسے بھی اپنے پروردگار سے ملنے کی آرزو ہو اسے چاہئے کہ نیک اعمال کرے اور اپنے پروردگار کی عبادت[3] میں کسی کو بھی شریک نہ کرے.",
      "en": "Say, \"I am only a man like you, to whom has been revealed that your god is one God. So whoever would hope for the meeting with his Lord - let him do righteous work and not associate in the worship of his Lord anyone.\"",
      "footnotesUr": "[1] اس لئے میں بھی رب کی باتوں کا احاطہ نہیں کر سکتا۔\n[2] البتہ مجھے یہ امتیاز حاصل ہے کہ مجھ پر وحی آتی ہے۔ اسی وحی کی بدولت میں نے اصحاب کہف اور ذوالقرنین کے متعلق اللہ کی طرف سے نازل کردہ وہ باتیں بیان کی ہیں جن پر مرور ایام کی دبیز تہیں پڑی ہوئی تھیں یا ان کی حقیقت افسانوں میں گم ہوگئی تھی۔ علاوہ ازیں اس وحی میں سب سے اہم حکم یہ دیا گیا ہے کہ تم سب کا معبود صرف ایک ہے۔\n[3] عمل صالح وہ ہے جو سنت کے مطابق ہو، یعنی جو اپنے رب کی ملاقات کا یقین رکھتا ہے، اسے چاہیے کہ ہر عمل سنت نبوی کے مطابق کرے اور دوسرا اللہ کی عبادت میں کسی کو شریک نہ ٹھہرائے، اس لئے کہ بدعت اور شرک دونوں ہی ضبط اعمال کا سبب ہیں۔ اللہ تعالٰی ان دونوں سے ہر مسلمان کو مفوظ رکھے۔",
      "footnotesEn": null,
